# --- Circuit Breaker Tests ---
class TestCircuitBreaker:
    def test_initial_state_closed(self, circuit_breaker):
        """Circuit starts closed."""
        assert circuit_breaker.state == "CLOSED"
        assert circuit_breaker.failure_count == 0

    def test_success_resets_failures(self, circuit_breaker):
        """Successful calls reset failure count."""
        circuit_breaker.record_failure()
        circuit_breaker.record_failure()
        circuit_breaker.record_success()
        assert circuit_breaker.failure_count == 0
        assert circuit_breaker.state == "CLOSED"

    def test_open_after_threshold(self, circuit_breaker):
        """Circuit opens after threshold failures."""
        for _ in range(3):
            circuit_breaker.record_failure()
        assert circuit_breaker.state == "OPEN"

    def test_half_open_after_timeout(self, circuit_breaker):
        """Circuit transitions to half-open after reset timeout."""
        for _ in range(3):
            circuit_breaker.record_failure()
        assert circuit_breaker.state == "OPEN"

        # Simulate timeout
        time.sleep(1.1)
        assert circuit_breaker.state == "HALF_OPEN"

    def test_half_open_success_closes(self, circuit_breaker):
        """Success in half-open closes circuit."""
        for _ in range(3):
            circuit_breaker.record_failure()
        time.sleep(1.1)
        assert circuit_breaker.state == "HALF_OPEN"

        circuit_breaker.record_success()
        assert circuit_breaker.state == "CLOSED"
        assert circuit_breaker.failure_count == 0

    def test_half_open_failure_reopens(self, circuit_breaker):
        """Failure in half-open reopens circuit."""
        for _ in range(3):
            circuit_breaker.record_failure()
        time.sleep(1.1)
        assert circuit_breaker.state == "HALF_OPEN"

        circuit_breaker.record_failure()
        assert circuit_breaker.state == "OPEN"

    def test_can_execute_when_closed(self, circuit_breaker):
        """Requests allowed when closed."""
        assert circuit_breaker.can_execute() is True

    def test_can_execute_when_open(self, circuit_breaker):
        """Requests blocked when open."""
        for _ in range(3):
            circuit_breaker.record_failure()
        assert circuit_breaker.can_execute() is False

    def test_can_execute_when_half_open(self, circuit_breaker):
        """Requests allowed in half-open (trial)."""
        for _ in range(3):
            circuit_breaker.record_failure()
        time.sleep(1.1)
        assert circuit_breaker.can_execute() is True

    @given(st.integers(min_value=1, max_value=100))
    @hyp_settings(max_examples=50)
    def test_threshold_property(self, gateway_module, threshold):
        """Property: circuit opens exactly at threshold."""
        cb = gateway_module.CircuitBreaker(
            failure_threshold=threshold,
            reset_timeout_sec=60,
        )
        for _ in range(threshold - 1):
            cb.record_failure()
        assert cb.state == "CLOSED"
        cb.record_failure()
        assert cb.state == "OPEN"


