# --- Concurrency / Stress Tests ---
class TestConcurrency:
    @pytest.mark.asyncio
    async def test_concurrent_ingestion(self, gateway_module):
        """High-frequency concurrent ingestion maintains integrity."""
        app = gateway_module.app
        # Use ASGI transport for async testing
        from httpx import AsyncClient, ASGITransport

        async with AsyncClient(
            transport=ASGITransport(app=app), base_url="http://test"
        ) as ac:
            tasks = []
            for i in range(100):
                tasks.append(
                    ac.post("/telemetry", json={
                        "source_id": f"sensor-{i}",
                        "metric_name": "temperature",
                        "value": float(i),
                    })
                )
            responses = await asyncio.gather(*tasks)
            assert all(r.status_code == 200 for r in responses)

    @pytest.mark.asyncio
    async def test_buffer_thread_safety(self, gateway_module):
        """Concurrent buffer access doesn't corrupt state."""
        buffer = gateway_module.TelemetryBuffer(max_size=1000)

        async def writer():
            for i in range(100):
                payload = gateway_module.TelemetryPayload(
                    source_id=f"sensor-{i}",
                    metric_name="temp",
                    value=float(i),
                )
                buffer.append(payload)
                await asyncio.sleep(0.001)

        async def reader():
            for _ in range(100):
                items = buffer.get_all()
                assert len(items) <= 1000
                await asyncio.sleep(0.001)

        await asyncio.gather(writer(), reader(), writer(), reader())


