# --- Performance / Load Tests ---
class TestPerformance:
    def test_ingestion_latency(self, gateway_module, client):
        """P95 latency under 50ms for single ingestion."""
        latencies = []
        for _ in range(100):
            start = time.perf_counter()
            response = client.post("/telemetry", json={
                "source_id": "sensor-001",
                "metric_name": "temperature",
                "value": 23.5,
            })
            latencies.append(time.perf_counter() - start)
            assert response.status_code == 200

        latencies.sort()
        p95 = latencies[int(len(latencies) * 0.95)]
        assert p95 < 0.05  # 50ms

    def test_throughput(self, gateway_module, client):
        """Sustained throughput above 1000 req/s (simulated)."""
        start = time.perf_counter()
        for _ in range(100):
            client.post("/telemetry", json={
                "source_id": "sensor-001",
                "metric_name": "temperature",
                "value": 23.5,
            })
        elapsed = time.perf_counter() - start
        rps = 100 / elapsed
        assert rps > 100  # Conservative threshold for CI


