        for i in range(10):
            response = client.post("/telemetry", json={
                "source_id": f"sensor-{i}",
                "metric_name": "temperature",
                "value": float(i),
            })
            assert response.status_code == 200

        items = gateway_module.telemetry_buffer.get_all()
        sources = {item.source_id for item in items}
        assert len(sources) == 10


